-- Western Plaguelands: spawns, loot and templates the Cataclysm quests need. Based on Legends of Azeroth 5.4.8; the
-- number of copies of the busy battle entries follows the spawn counts on Wowhead MoP Classic (the 5.4.8 data holds
-- every sniffed copy of the Andorhal battle as its own spawn), copies picked evenly across the sniffed area.
--
-- Quests blocked by the missing spawns: 26922 and 27161 (Stickbone Berserker), 27085 (Andorhal Defender), 27086 and
-- 27199 (Force-Commander, War-Captain), 27084 (Ebon Gargoyle), 27173 (Forsaken Outrider), 27201 (Lesser Val'kyr),
-- 27202 (Forsaken Trooper), 27204 (Aradne), 26956 (Thrashing Pumpkin, Pome Wraith, Corn Stalker), 26938 (Opengut
-- Behemoth), 26957 and 27017 (Del Gahrron), 27171 (Skeletal Flayer and Sorcerer drops), 26999 (three sample drops).

DELETE FROM `creature` WHERE `guid` BETWEEN 8316200 AND 8316408;

-- The sniffed battle creatures were friendly placeholders: use the 5.4.8 factions and make the Opengut Behemoth a target.
UPDATE `creature_template` SET `faction_A`=974, `faction_H`=974 WHERE `entry` IN (44329, 45098);
UPDATE `creature_template` SET `faction_A`=2213, `faction_H`=2213 WHERE `entry`=45209;
UPDATE `creature_template` SET `faction_A`=1801, `faction_H`=1801 WHERE `entry` IN (45235, 45240);
UPDATE `creature_template` SET `faction_A`=68, `faction_H`=68 WHERE `entry`=45239;
UPDATE `creature_template` SET `npcflag`=0 WHERE `entry`=45098;

-- Skeletal Flayer and Skeletal Sorcerer carry the 27171 quest items and are level 35 and 36 in this zone.
UPDATE `creature_template` SET `minlevel`=35, `maxlevel`=36 WHERE `entry` IN (1783, 1784);
DELETE FROM `creature_loot_template` WHERE `item` IN (60760, 60761, 60763, 60863, 60864) AND `entry` IN (1783, 1784, 1817, 1822, 1824);

-- Skeletal Sorcerer casts Frostbolt and Fire Nova.
UPDATE `creature_template` SET `AIName`='SmartAI' WHERE `entry`=1784;
DELETE FROM `smart_scripts` WHERE `entryorguid`=1784 AND `source_type`=0;
